CREATE OR REPLACE FUNCTION public.pm_quote_calendar_allocations(_quote uuid,_start date) RETURNS jsonb LANGUAGE sql STABLE SET search_path=public AS $$ WITH rows AS (SELECT jsonb_build_object('id',a.id,'stage_id',a.stage_id,'resource_id',a.resource_id,'resource_name',r.name,'hours_per_day',a.hours_per_day,'start_date',pm_calendar_shift(_start,pm_relative_offset(a.start_date)),'end_date',pm_calendar_shift(_start,pm_relative_offset(a.end_date))) item FROM quote_allocations a JOIN quote_stages s ON s.id=a.stage_id JOIN pm_resources r ON r.id=a.resource_id WHERE a.quote_id=_quote AND s.stage_kind<>'retainer_monthly' UNION ALL SELECT jsonb_build_object('id',a.id,'stage_id',a.stage_id,'resource_id',a.resource_id,'resource_name',r.name,'month_index',m,'hours_per_day',(pm_relative_offset(a.end_date)-pm_relative_offset(a.start_date)+1)*a.hours_per_day/greatest(1,(SELECT count(*) FROM generate_series((date_trunc('month',_start)+make_interval(months=>m))::timestamp,(date_trunc('month',_start)+make_interval(months=>m+1)-interval '1 day')::timestamp,interval '1 day') d WHERE extract(isodow FROM d)<6 AND NOT EXISTS(SELECT 1 FROM holidays h WHERE h.data=d::date))),'start_date',(date_trunc('month',_start)+make_interval(months=>m))::date,'end_date',(date_trunc('month',_start)+make_interval(months=>m+1)-interval '1 day')::date) FROM quote_allocations a JOIN quote_stages s ON s.id=a.stage_id JOIN pm_resources r ON r.id=a.resource_id CROSS JOIN LATERAL generate_series(0,greatest(1,coalesce(s.retainer_months,1))-1) m WHERE a.quote_id=_quote AND s.stage_kind='retainer_monthly') SELECT coalesce(jsonb_agg(item),'[]'::jsonb) FROM rows $$;
REVOKE ALL ON FUNCTION public.pm_quote_calendar_allocations(uuid,date) FROM PUBLIC,anon,authenticated;
DO $migration$ DECLARE definition text; start_at integer; end_at integer; BEGIN SELECT pg_get_functiondef('public.pm_quote_conversion_preview(uuid,date)'::regprocedure) INTO definition; start_at:=strpos(definition,'SELECT coalesce(jsonb_agg(jsonb_build_object(''id'',a.id'); end_at:=strpos(definition,'revision_data:='); IF start_at=0 OR end_at<=start_at THEN RAISE EXCEPTION 'Unexpected preview definition'; END IF; definition:=left(definition,start_at-1)||'allocations:=pm_quote_calendar_allocations(_quote,start_day);'||chr(10)||substr(definition,end_at); EXECUTE definition;
SELECT pg_get_functiondef('public.pm_convert_relative_quote(uuid,date,text)'::regprocedure) INTO definition; definition:=replace(definition,'child_id,a.resource_id,month_start,month_end,a.hours_per_day,a.allocation_percentage','child_id,a.resource_id,month_start,month_end,(SELECT (value->>''hours_per_day'')::numeric FROM jsonb_array_elements(preview->''allocations'') WHERE value->>''id''=a.id::text AND (value->>''month_index'')::integer=m),a.allocation_percentage'); EXECUTE definition; END $migration$;